            Issue.record("expected a baptism event, got \(String(describing: detail))")
            return
        }
        #expect(b.child.forename == "Sarah Jane")
        #expect(b.child.surname == "KENWORTHY")
        #expect(b.child.sex == "F")
        #expect(b.child.abode == "Makeney")
        #expect(b.child.placeOfBirth == "Milford", "extended person_place_birth is birthplace evidence")
        #expect(b.child.countyOfBirth == "Derbyshire")
        #expect(b.birthDate == "2 Jan 1845", "birth date stays distinct from baptism date")
        #expect(b.baptismDate == "12 Mar 1845")
        #expect(b.isPrivate == true)
        #expect(b.father?.forename == "John")
        #expect(b.father?.occupation == "Nailer", "father's occupation is typed, not rawFields-only")
        #expect(b.father?.abode == "Makeney")
        #expect(b.mother?.person.forename == "Mary")
        #expect(b.mother?.placePriorToMarriage == "Heage", "maiden-origin lead survives typed")
        #expect(b.mother?.countyPriorToMarriage == "Derbyshire")
    }

