/// The wire-through: FreeREGSource attaches the typed payload and projects
/// flat parents baptism-only (the DS-10 producer guard).
@MainActor
struct FreeREGTypedAttachmentTests {

    private func baseParish(eventType: String) -> ParishRecord {
        ParishRecord(
            common: RecordCommon(
                id: "freereg_test1", sourceID: "freereg", name: "Test Person",
                surname: "Person", givenName: "Test",
                detailURL: "https://www.freereg.org.uk/search_records/abc123",
                rawFields: ["parish": "Duffield"]
            ),
            eventType: eventType, eventYear: 1850, parish: "Duffield", county: "Derbyshire"
        )
    }

    @Test func mergedBaptismCarriesTypedDetailAndFlatParents() {
        let pairs = FreeREGSource.parseDetailPairs(FreeREGDetailMapperTests.liveBaptismHTML)
        let fields = FreeREGSource.detailFields(fromPairs: pairs)
        let merged = FreeREGSource.mergedDetailRecord(
            base: baseParish(eventType: "baptism"), detailFields: fields, pairs: pairs)
        guard case .parish(let p) = merged else { Issue.record("expected parish"); return }
        #expect(p.detail != nil, "typed payload attached")
        #expect(p.fatherName == "John KENWORTHY", "baptism keeps flat parents")
        #expect(p.motherName == "Mary KENWORTHY")
        #expect(p.common.id == "freereg_test1", "identity never flips (FT-12)")
    }

    @Test func mergedMarriageProjectsNoFlatParents() {
        let pairs = FreeREGSource.parseDetailPairs(FreeREGDetailMapperTests.liveMarriageHTML)
        let fields = FreeREGSource.detailFields(fromPairs: pairs)
        let merged = FreeREGSource.mergedDetailRecord(
            base: baseParish(eventType: "marriage"), detailFields: fields, pairs: pairs)
        guard case .parish(let p) = merged else { Issue.record("expected parish"); return }
        #expect(p.fatherName == nil,
                "a groom's/bride's father is NOT the subject's father — DS-10 producer guard")
        #expect(p.motherName == nil)
        guard case .marriage(let m)? = p.detail?.event else { Issue.record("typed marriage expected"); return }
        #expect(m.groomFather?.forename == "Samuel", "the fathers live in the typed detail under true roles")
    }

    @Test func mergedBurialProjectsNoFlatParents() {
        let pairs = FreeREGSource.parseDetailPairs(FreeREGDetailMapperTests.liveBurialHTML)
        let fields = FreeREGSource.detailFields(fromPairs: pairs)
        let merged = FreeREGSource.mergedDetailRecord(
            base: baseParish(eventType: "burial"), detailFields: fields, pairs: pairs)
        guard case .parish(let p) = merged else { Issue.record("expected parish"); return }
        #expect(p.fatherName == nil, "a burial's next-of-kin is not the subject's parent")
        guard case .burial(let b)? = p.detail?.event else { Issue.record("typed burial expected"); return }
        #expect(b.relative?.forename == "John")
    }

    // MARK: - Producer/guard agreement (DS-10, verify finding 2026-07-29)

    @Test func blankTypeSearchRowWithBaptismDetailKeepsGateFiring() {
        // An all-types .parish search row can carry a blank type cell
        // (eventType falls back to "parish") while its enriched detail
        // page proves baptism. The producer populates flat parents from
        // the TYPED event — and the scorer's DS-10 gate must fire on the
        // same basis, or namesake-baptism protection silently lapses.
        let pairs = FreeREGSource.parseDetailPairs(FreeREGDetailMapperTests.liveBaptismHTML)
        let fields = FreeREGSource.detailFields(fromPairs: pairs)
        let merged = FreeREGSource.mergedDetailRecord(
            base: baseParish(eventType: "parish"), detailFields: fields, pairs: pairs)
        guard case .parish(let p) = merged else { Issue.record("expected parish"); return }
        // Producer: typed baptism → flat parents populated despite the
        // blank/fallback search-row type.
        #expect(p.fatherName == "John KENWORTHY")
        guard case .baptism = p.detail?.event else { Issue.record("typed baptism expected"); return }

        // Scorer: the familyContext gate fires via the typed event.
        let subject = ResearchSubject(
            surname: "KENWORTHY", givenName: "Sarah",
            birthYearFrom: 1843, birthYearTo: 1847,
            gender: .female, region: .englandAndWales,
            mode: .verify,
            familyContext: FamilyContext(
                spouseName: nil, spouseSurname: nil, spouseGivenName: nil,
                spouseFatherSurname: nil, childNames: [],
                fatherName: "William KENWORTHY", fatherSurname: "KENWORTHY", fatherGivenName: "William",
                motherName: nil, motherSurname: nil, motherGivenName: nil)
        )
        let result = RecordScorer.classify(record: merged, subject: subject, searchType: .parish)
        let family = result.gates.first { $0.gate == .familyContext }
        #expect(family?.outcome == .softFail,
                "record father John vs linked father William must soft-fail even when eventType is the 'parish' fallback — got \(String(describing: family?.outcome))")
    }

    // MARK: - Codable compatibility

    @Test func parishRecordWithDetailRoundTrips() throws {
        let pairs = FreeREGSource.parseDetailPairs(FreeREGDetailMapperTests.liveMarriageHTML)
        let detail = FreeREGDetailMapper.detail(fromLabelledPairs: pairs, typeHint: "marriage")
        let record = SourceRecord.parish(ParishRecord(
            common: RecordCommon(id: "rt1", sourceID: "freereg", rawFields: [:]),
            eventType: "marriage", eventYear: 1868, detail: detail
        ))
        let data = try JSONEncoder().encode(record)
        let decoded = try JSONDecoder().decode(SourceRecord.self, from: data)
        guard case .parish(let p) = decoded, case .marriage(let m)? = p.detail?.event else {
            Issue.record("round-trip lost the typed payload")
            return
        }
        #expect(m.witnesses.count == 3)
        #expect(m.brideFather?.forename == "John William")
    }

    @Test func oldPersistedJSONWithoutDetailStillDecodes() throws {
        // A nil-detail record encodes WITHOUT the key (synthesized
        // encodeIfPresent) — i.e. byte-shape-identical to every
        // evidence_records.record_json row written before this field
        // existed — and must decode back with detail == nil.
        let record = SourceRecord.parish(ParishRecord(
            common: RecordCommon(id: "freereg_old", sourceID: "freereg", rawFields: [:]),
            eventType: "baptism", eventYear: 1845, fatherName: "John SMITH"
        ))
        let data = try JSONEncoder().encode(record)
        let json = String(decoding: data, as: UTF8.self)
        #expect(!json.contains("\"detail\""),
                "nil detail must be OMITTED from JSON — proving the pre-field shape is what we still write and read")
        let decoded = try JSONDecoder().decode(SourceRecord.self, from: data)
        guard case .parish(let p) = decoded else { Issue.record("expected parish"); return }
        #expect(p.detail == nil, "absent key decodes to nil — additive-safe")
        #expect(p.fatherName == "John SMITH")
    }
}
